---@class GearHint
---@field targetPoint           UnityEngine.Transform     @ 生成Hint的世界坐标位置
---@field ui_hintPrefab         UnityEngine.RectTransform @ Hint的Prefab
---@field ui_hintPrefabInPC     UnityEngine.RectTransform @ Hint的Prefab pc 版
local GearHint = Class('GearHint')
-- 外部调用
-- local GearHint = import('Game.DreamSpace.Hint.GearHint')

-- ========================================================

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程

---@type LuaParametersReader
local LuaParametersReader = import('Game.Utils.LuaParametersReader')

local DreamSpaceLuaUtils = import('Game.DreamSpace.Tools.DreamSpaceLuaUtils')

local DreamSpaceStates = import('Game.DreamSpace.Tools.DreamSpaceStates')
---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Transform = CS.UnityEngine.Transform
local Button = CS.UnityEngine.UI.Button
local RectTransform = CS.UnityEngine.RectTransform
local Vector3 = CS.UnityEngine.Vector3


--- funtoy:
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool

local DreamSpaceUtils = CS.DreamSpace.DreamSpaceUtils
local GearHintCalculate = CS.InteractableHint.GearHintCalculate
local LuaBehaviour = CS.Engine.Modules.LuaBehaviour
local LuaParameters = CS.Engine.Modules.LuaParameters
local GlobalsInDreamSpace = CS.DreamSpace.GlobalsInDreamSpace



-- ========================================================


-- 3段动画:
local animationStr_showIn        = "ActionDreamlandHintPointNode_Probe"
local animationStr_showOff        = "ActionDreamlandHintPointNode_Data"
local animationStr_off_2_in      = "ActionDreamlandHintPointNode_Probe-Data"
local animationStr_in_2_off      = "ActionDreamlandHintPointNode_Data-Probe"



-- =========================== 全体实例 =============================

-- 存储所有 inScreen 的实例:
local allInstances = {} -- map  [id,instance]

-- 找到第一个 有效实例, 或 nil;  -- todo: 可升级为: 找到离主角最近的一个 实例
function GearHint._FindFirstInstance()
    for k,v in pairs(allInstances) do 
        if isNotNull(v) then 
            return v
        end 
    end 
    return nil
end


-- 每个 instance 分配一个 id:
local idCounter = 1 -- 
function GearHint._GetId()
    idCounter = idCounter + 1
    return idCounter
end


function GearHint.InitStatics()
    idCounter = 1
    allInstances = {}
end

-- ========================================================


function GearHint:__init()
    self.controller = nil
    self.isInit = false;
    self.WhenButtonPressed = nil -- 函数指针

    self.state = "" -- "Hide", "InScreen", "OffScreen"
end


function GearHint:__delete()
    self.co_1 = nil
end



function GearHint:Awake()
    KTool.SetActive(self.controller.gameObject, true);
end


function GearHint:Start()
    KTool.SetActive(self.controller.gameObject, true);

    self.transform = self.controller.gameObject.transform

    self.id = GearHint._GetId()

    assert( self.ui_hintPrefab )
    assert( self.ui_hintPrefabInPC )

    assert( self.targetPoint )

    self.luaParams = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( self.luaParams )


    self.gearHintCalculate = KTool.GetComponent(self.controller.gameObject, typeof(GearHintCalculate))

    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = cs_coroutine.start(self.DelayInit, self)
end



function GearHint:DelayInit() 

    -- 先等待一帧, 等新场景中新的 SwitchablePlayer 实例被创建
    coroutine.yield(Yielders.EndOfFrame)
    
    -- ----- role ------:
    -- 只会查找 N 次, 还是找不到就放弃 hint 功能了;

    self.role = nil
    for i=0, DreamSpaceStates.DelayInitWaitFrames do 

        self.role = GlobalsInDreamSpace.FindComponent("vTargetFollow")
        if isNotNull(self.role) then
            break
        end
        coroutine.yield(Yielders.EndOfFrame)
    end

    if isNull(self.role) then
        printError( false, "始终没能找到 gamoebj: SwitchablePlayer/VTarget/Follow, 请查找原因" )
        return
    end

    ---
    local RoleControllerRootCanvasMgr = import('Game.DreamSpace.UI.RoleControllerRootCanvasMgr'):GetInstance()
    RoleControllerRootCanvasMgr:CheckOrInitSync()
    local parentUICanvas = RoleControllerRootCanvasMgr.dynamicsCanvas
    assert( parentUICanvas )

    -- build ui hint:
    local hintPrefab = nil 
    local uiHintLuaStr = "Game.DreamSpace.Hint.GearHintUI"
    if DreamSpaceStates.isWindowsPlatform then
        hintPrefab = self.ui_hintPrefabInPC
    else
        hintPrefab = self.ui_hintPrefab
    end

    self.hintRTF = Object.Instantiate( hintPrefab, parentUICanvas.transform )
    self.hintRTF.name = "ActionDreamlandHintPointNode_" .. tostring(self.id)


    self.gearHintUI = DreamSpaceLuaUtils.GetLuaScr(self.hintRTF.gameObject, uiHintLuaStr )
    assert( self.gearHintUI )

    if DreamSpaceStates.isWindowsPlatform == true then 
        self.gearHintUI:SetPCKey( "E" )
    end 

    self.gearHintUI:SetInteractable( false ) -- 阻止交互


    -- 选择近景 显示哪个图片:
    self.nearImageIdx = LuaParametersReader.Read( self.luaParams, "nearImageIdx", LuaParametersReader.Type.Int )
    self.gearHintUI:SetNearImage( self.nearImageIdx )


    self.gearHintCalculate:Init(
        self.hintRTF, self.hintRTF, self.targetPoint, self.role
    )


    self:SetActive( false, false )

    self.gearHintCalculate.OnSetActive                  = Bind( self, self.SetActive)

    -----:
    self.isInit = true
end


function GearHint:OnDestroy()
    allInstances[self.id] = nil
    DreamSpaceLuaUtils.StopCoroutine( self.co_1 )
    self.co_1 = nil
    ---
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --



function GearHint:GetIsActive()
    return self.gearHintCalculate.isActive
end

function GearHint:SetIsActive( val_ )
    self.gearHintCalculate.isActive = val_
end



---@param isInScreenActive_ boolean
---@param isOffscreenActive_ boolean
function GearHint:SetActive( isInScreenActive_, isOffscreenActive_ )

    if (isInScreenActive_ == false) and (isOffscreenActive_ == false) then
        -- to Hide --:

        if self.state ~= "Hide"  then 
            self.state = "Hide"
            --print( "~~~~ to Hide" )

            self.gearHintUI:SetInteractable( false )
            KTool.SetActive( self.hintRTF.gameObject, false )

            --currentActiveGearHint = nil
            allInstances[self.id] = nil
        end    


    elseif (isInScreenActive_ == true) and (isOffscreenActive_ == false) then
        if self.state == "Hide" then
            -- Hide to InScreen:
            --print( "~~~~  Hide to InScreen" )

            KTool.SetActive( self.hintRTF.gameObject, true )
            self.gearHintUI:SetInteractable( false )
            self.gearHintUI.ui_hintAnimation:Play( animationStr_showIn )


        elseif self.state == "OffScreen" then
            -- OffScreen to InScreen:
            --print( "~~~~  OffScreen to InScreen" )

            KTool.SetActive( self.hintRTF.gameObject, true )
            self.gearHintUI:SetInteractable( false )
            self.gearHintUI.ui_hintAnimation:Play( animationStr_in_2_off )

        end
        self.state = "InScreen"
        --currentActiveGearHint = nil
        allInstances[self.id] = nil

    elseif (isInScreenActive_ == false) and (isOffscreenActive_ == true) then
        -- inScreen to offScreen --:


        if self.state == "Hide" then
            -- Hide to OffScreen:
            --print( "~~~~  Hide to OffScreen" )
            KTool.SetActive( self.hintRTF.gameObject, true )
            self.gearHintUI:SetInteractable( true )

            self.gearHintUI.ui_hintAnimation:Play( animationStr_showOff )


        elseif self.state == "InScreen" then
            -- InScreen to OffScreen:
            --print( "~~~~  InScreen to OffScreen" )

            --print( "gearHint -- inScreen to offScreen" )
            KTool.SetActive( self.hintRTF.gameObject, true )
            self.gearHintUI:SetInteractable( true )
            self.gearHintUI.ui_hintAnimation:Play( animationStr_off_2_in )

        end
        self.state = "OffScreen"
        --currentActiveGearHint = self
        allInstances[self.id] = self

    else 
        -- 皆为 true, 异常: 
        assert( false, "参数异常" )
    end
end 




---@param call_ UnityEngine.Events.UnityAction
function GearHint:BindHintButton(  call_ )
    if self.isInit == false then
        return
    end
    self.gearHintUI.ui_inScreenButton.onClick:AddListener( call_ )

    self.WhenButtonPressed = call_
end


-- static
-- pc模式时, 按下解谜按键后调用
function GearHint.TriggerGearInPCMode()
    local currentActiveGearHint = GearHint._FindFirstInstance()
    if currentActiveGearHint ~= nil then 
        assert( currentActiveGearHint.WhenButtonPressed ~= nil )
        currentActiveGearHint.WhenButtonPressed()
    end
end 



return GearHint
